class DIContainer{constructor(){this.services=new Map,this.singletons=new Map}register(e,s,t={singleton:!0}){if(this.services.has(e))throw new Error(`Service '${e}' is already registered.`);this.services.set(e,{definition:s,options:t})}resolve(e){const s=this.services.get(e);if(!s)throw new Error(`Service '${e}' is not registered.`);const{definition:t,options:n}=s;if(n.singleton&&this.singletons.has(e))return this.singletons.get(e);const i="function"==typeof t?t(this):t;return n.singleton&&this.singletons.set(e,i),i}}const container=new DIContainer;export{container,DIContainer};
